/**
 * Regenerates the derived paradigm data files from the rules below:
 *   paradigm/aliases/semantic-to-palette.json
 *   paradigm/matrices/component.json
 *
 * The generated files are committed and are what the plugin, the validator and
 * the tests read. Re-run with `npm run paradigm:generate` after editing a rule
 * and commit the diff, so a reviewer sees the expanded table, not just the rule.
 */
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const paradigmDir = path.join(here, '..', 'paradigm');

const vocabulary = JSON.parse(await fs.readFile(path.join(paradigmDir, 'vocabulary.json'), 'utf8'));

const writeJson = async (relative, data) => {
  const target = path.join(paradigmDir, relative);
  await fs.mkdir(path.dirname(target), { recursive: true });
  await fs.writeFile(target, `${JSON.stringify(data, null, 2)}\n`, 'utf8');
  return target;
};

/* ------------------------------------------------------------------ semantic */

const TONE_FAMILY = {
  theme: 'primary',
  normal: 'neutral',
  success: 'success',
  warning: 'warning',
  error: 'error',
  info: 'info'
};

/**
 * Chromatic ramps carry s1…s12; steps follow the ALD semantic step map
 * (control primary 8 / soft 4 keep parity with control-*-Background and
 * control-*-lightBackground).
 */
const CHROMATIC_STEP = {
  text: {
    primary: 10,
    secondary: 7,
    tertiary: 5,
    muted: 6,
    inverse: 1,
    title: 12,
    caption: 9,
    disabled: 4
  },
  box: { primary: 8, secondary: 4, soft: 2, canvas: 1, inverse: 12, muted: 3 },
  border: { primary: 8, secondary: 6, tertiary: 4, soft: 2, focus: 8 },
  control: { primary: 8, soft: 4, muted: 2, canvas: 1, inverse: 12 }
};

/**
 * The neutral ramp carries s1…s14, so tone `normal` gets its own steps. The
 * control row keeps parity with ALD control-normal-lightBackground-1|2 and
 * control-normal-Background-3 (neutral 3 / 4 / 6), which is why its quiet
 * surfaces sit above the chromatic ones.
 */
const NEUTRAL_STEP = {
  text: {
    primary: 12,
    secondary: 11,
    tertiary: 9,
    muted: 8,
    inverse: 1,
    title: 13,
    caption: 10,
    disabled: 7
  },
  box: { primary: 3, secondary: 4, soft: 2, canvas: 1, inverse: 13, muted: 5 },
  border: { primary: 6, secondary: 5, tertiary: 4, soft: 3, focus: 8 },
  control: { primary: 6, soft: 3, muted: 4, canvas: 1, inverse: 13 }
};

/**
 * Slots whose target must flip per mode instead of riding the palette mode.
 * `onColor` is text on top of a filled brand surface, so it stays near-white in
 * both themes: palette dark mode inverts the neutral ramp, hence s1 / s14.
 */
const PER_MODE_SLOT = {
  onColor: { light: 'palette/neutral/s1', dark: 'palette/neutral/s14' }
};

const buildSemanticAliases = () => {
  const semantic = vocabulary.namespaces.semantic;
  const useSlot = semantic.matrix.find((m) => m.key === 'use' && m.constrains === 'slot').allow;
  const entries = {};

  for (const use of semantic.slots.use) {
    for (const tone of semantic.slots.tone) {
      for (const slot of useSlot[use]) {
        const source = `${use}/${tone}-${slot}`;
        if (PER_MODE_SLOT[slot]) {
          entries[source] = { ...PER_MODE_SLOT[slot] };
          continue;
        }
        const family = TONE_FAMILY[tone];
        const step = family === 'neutral' ? NEUTRAL_STEP[use][slot] : CHROMATIC_STEP[use][slot];
        if (step === undefined) throw new Error(`no step mapped for ${source}`);
        const target = `palette/${family}/s${step}`;
        entries[source] = { light: target, dark: target };
      }
    }
  }

  return {
    target: 'palette',
    description:
      'semantic → palette alias table. Generated by scripts/generate-paradigm.mjs from the ALD semantic step map (primary 8, text 10/7/5, secondary 4, soft 2) with fail → error and infomation → info corrected.',
    count: Object.keys(entries).length,
    aliases: entries
  };
};

/* ----------------------------------------------------------------- component */

/** Types whose surfaces are interactive controls; the rest read as boxes. */
const CONTROL_TYPE = new Set([
  'button',
  'input',
  'checkbox',
  'radio',
  'switch',
  'select',
  'slider',
  'progress'
]);

const LEVEL_TONE = {
  primary: 'theme',
  secondary: 'normal',
  tertiary: 'normal',
  danger: 'error',
  success: 'success',
  neutral: 'normal'
};

const TEXT_SLOT_BY_STATE = {
  rest: 'primary',
  hover: 'primary',
  active: 'primary',
  focus: 'primary',
  selected: 'primary',
  checked: 'primary',
  loading: 'muted',
  disabled: 'disabled'
};

const CONTROL_SLOT_BY_STATE = {
  filled: {
    rest: 'primary',
    hover: 'primary',
    active: 'primary',
    focus: 'primary',
    selected: 'primary',
    checked: 'primary',
    loading: 'soft',
    disabled: 'muted'
  },
  soft: {
    rest: 'soft',
    hover: 'soft',
    active: 'muted',
    focus: 'soft',
    selected: 'soft',
    checked: 'primary',
    loading: 'soft',
    disabled: 'muted'
  },
  bare: {
    rest: 'canvas',
    hover: 'soft',
    active: 'muted',
    focus: 'canvas',
    selected: 'soft',
    checked: 'primary',
    loading: 'canvas',
    disabled: 'canvas'
  }
};

const BOX_SLOT_BY_STATE = {
  filled: {
    rest: 'primary',
    hover: 'secondary',
    active: 'soft',
    focus: 'primary',
    selected: 'secondary',
    checked: 'secondary',
    loading: 'soft',
    disabled: 'muted'
  },
  soft: {
    rest: 'soft',
    hover: 'secondary',
    active: 'secondary',
    focus: 'soft',
    selected: 'secondary',
    checked: 'secondary',
    loading: 'soft',
    disabled: 'muted'
  },
  bare: {
    rest: 'canvas',
    hover: 'soft',
    active: 'soft',
    focus: 'canvas',
    selected: 'soft',
    checked: 'soft',
    loading: 'canvas',
    disabled: 'canvas'
  }
};

const BORDER_SLOT_BY_STATE = {
  rest: 'primary',
  hover: 'secondary',
  active: 'tertiary',
  focus: 'focus',
  selected: 'primary',
  checked: 'primary',
  loading: 'soft',
  disabled: 'soft'
};

const surfaceFamily = (component) => {
  if (component === 'filled') return 'filled';
  if (component === 'soft') return 'soft';
  return 'bare';
};

const semanticUseFor = (type, role) => {
  if (role === 'foreground' || role === 'label' || role === 'icon') return 'text';
  if (role === 'border' || role === 'focusRing') return 'border';
  return CONTROL_TYPE.has(type) ? 'control' : 'box';
};

const semanticSlotFor = ({ type, component, role, state }) => {
  if (role === 'focusRing') return 'focus';
  if (role === 'border') return BORDER_SLOT_BY_STATE[state];
  if (role === 'foreground' || role === 'label' || role === 'icon') {
    if (state === 'disabled') return 'disabled';
    if (component === 'filled') return 'onColor';
    return TEXT_SLOT_BY_STATE[state];
  }
  const table = CONTROL_TYPE.has(type) ? CONTROL_SLOT_BY_STATE : BOX_SLOT_BY_STATE;
  return table[surfaceFamily(component)][state];
};

const aliasFor = (entry) => {
  const use = semanticUseFor(entry.type, entry.role);
  const tone = LEVEL_TONE[entry.level];
  const slot = semanticSlotFor(entry);
  if (!slot) throw new Error(`no semantic slot for ${JSON.stringify(entry)}`);
  return `semantic/${use}/${tone}-${slot}`;
};

/**
 * Whitelisted recipes. Each recipe is a small cross product of variant × level ×
 * (role → states); the generator expands it into explicit entries so the
 * committed matrix stays a literal whitelist rather than a rule to re-derive.
 */
const RECIPES = [
  {
    type: 'button',
    components: ['filled', 'outlined', 'ghost', 'text'],
    levels: ['primary', 'secondary', 'danger'],
    roles: {
      background: ['rest', 'hover', 'active', 'loading', 'disabled'],
      foreground: ['rest', 'hover', 'loading', 'disabled'],
      focusRing: ['focus']
    }
  },
  {
    type: 'button',
    components: ['outlined'],
    levels: ['primary', 'secondary', 'danger'],
    roles: { border: ['rest', 'hover', 'active', 'disabled'] }
  },
  {
    type: 'input',
    components: ['outlined', 'soft'],
    levels: ['primary', 'neutral', 'danger'],
    roles: {
      background: ['rest', 'hover', 'disabled'],
      border: ['rest', 'hover', 'focus', 'disabled'],
      foreground: ['rest', 'disabled'],
      label: ['rest', 'disabled'],
      focusRing: ['focus']
    }
  },
  {
    type: 'checkbox',
    components: ['filled', 'outlined'],
    levels: ['primary', 'neutral'],
    roles: {
      background: ['rest', 'hover', 'checked', 'disabled'],
      border: ['rest', 'hover', 'checked', 'disabled'],
      icon: ['checked', 'disabled'],
      focusRing: ['focus']
    }
  },
  {
    type: 'switch',
    components: ['filled'],
    levels: ['primary', 'neutral'],
    roles: {
      background: ['rest', 'checked', 'disabled'],
      foreground: ['rest', 'checked', 'disabled'],
      focusRing: ['focus']
    }
  },
  {
    type: 'link',
    components: ['text'],
    levels: ['primary', 'neutral'],
    roles: {
      foreground: ['rest', 'hover', 'active', 'disabled'],
      focusRing: ['focus']
    }
  },
  {
    type: 'tag',
    components: ['filled', 'soft', 'outlined'],
    levels: ['primary', 'success', 'danger', 'neutral'],
    roles: {
      background: ['rest', 'hover', 'disabled'],
      foreground: ['rest', 'disabled']
    }
  },
  {
    type: 'tag',
    components: ['outlined'],
    levels: ['primary', 'success', 'danger', 'neutral'],
    roles: { border: ['rest', 'hover', 'disabled'] }
  }
];

const buildComponentMatrix = () => {
  const slots = vocabulary.namespaces.component.slots;
  const seen = new Set();
  const entries = [];

  for (const recipe of RECIPES) {
    for (const component of recipe.components) {
      for (const level of recipe.levels) {
        for (const [role, states] of Object.entries(recipe.roles)) {
          for (const state of states) {
            const entry = { type: recipe.type, component, level, role, state };
            for (const [slot, value] of Object.entries(entry)) {
              if (!slots[slot].includes(value)) {
                throw new Error(`"${value}" is not in the closed ${slot} vocabulary`);
              }
            }
            const leaf = `${component}-${level}-${role}-${state}`;
            const path = `${recipe.type}/${leaf}`;
            if (seen.has(path)) continue;
            seen.add(path);
            entries.push({ path, ...entry, alias: aliasFor(entry) });
          }
        }
      }
    }
  }

  entries.sort((a, b) => a.path.localeCompare(b.path));

  return {
    target: 'semantic',
    description:
      'Whitelisted component variables and their semantic aliases. Generated by scripts/generate-paradigm.mjs; no full cross product. Types outside this list keep their vocabulary reserved but are not created.',
    count: entries.length,
    types: [...new Set(entries.map((e) => e.type))],
    entries
  };
};

/* --------------------------------------------------------------------- write */

const semantic = buildSemanticAliases();
const component = buildComponentMatrix();

const written = [
  await writeJson('aliases/semantic-to-palette.json', semantic),
  await writeJson('matrices/component.json', component)
];

process.stdout.write(
  `semantic aliases: ${semantic.count}\ncomponent entries: ${component.count}\n${written.join('\n')}\n`
);
